]$catalog$::jsonb) as seed(
    id uuid, name_en text, name_ar text, category text, selling_price numeric,
    sizes text[], colors text[], stock_quantity integer, image_index integer
  )
), prepared as (
  select seed.*,
    case
      when seed.category in ('abayas', 'isdals', 'dresses', 'tshirts', 'pants') then '596c4367-1491-481f-b0f2-1825c2540ebd'::uuid
      when seed.category in ('sneakers', 'heels', 'slippers') then '2a304931-2230-4960-9e44-b19ed5e0178b'::uuid
      else '652f4263-d4e3-4bf6-a5c4-778e8a08c710'::uuid
    end as partner_id,
    pg_catalog.round(seed.selling_price * 0.60, 2) as cost_price,
    '/catalog/' || seed.category || '-' || pg_catalog.lpad(seed.image_index::text, 2, '0') || '.webp' as image_url
  from seed_source as seed
)
insert into public.products (
  id, partner_id, name_en, name_ar, description, description_ar, category,
  cost_price, selling_price, sizes, colors, stock_quantity, in_stock,
  is_available, image_url, created_at
)
select
  id, partner_id, name_en, name_ar,
  name_en || ' — ASO portfolio sample product.',
  name_ar || ' — منتج تجريبي من ASO.',
  category, cost_price, selling_price, sizes, colors, stock_quantity,
  stock_quantity > 0, true, image_url, pg_catalog.now()
from prepared
on conflict (id) do nothing;
